import subprocess
import xml.etree.ElementTree as ET
from collections import deque

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    capacity = int(root.attrib['capacity'])
    jobs = []
    for job_elem in root.findall('job'):
        job = {
            'id': job_elem.attrib['id'],
            'cmd': job_elem.attrib['cmd'],
            'weight': int(job_elem.attrib['weight'])
        }
        jobs.append(job)
    return capacity, jobs

def run_jobs(capacity, jobs):
    job_queue = deque(jobs)
    active_jobs = []
    job_results = {}

    while job_queue or active_jobs:
        # Find the earliest job in the queue that can be started
        for i, job in enumerate(job_queue):
            if sum(p.weight for p in active_jobs) + job['weight'] <= capacity:
                active_jobs.append(subprocess.Popen(job['cmd'].split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE))
                job_queue.remove(job)
                break
        else:
            # No job can be started; wait for some to finish
            for p in active_jobs:
                stdout, stderr = p.communicate()
                exit_code = p.returncode
                job_results[p._job_id] = exit_code
                active_jobs.remove(p)

    # Collect remaining jobs
    for p in active_jobs:
        stdout, stderr = p.communicate()
        exit_code = p.returncode
        job_results[p._job_id] = exit_code

    return job_results

def main():
    if len(sys.argv) != 2:
        print("Usage: python runjobs.py <jobs.xml>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    try:
        capacity, jobs = parse_xml(xml_path)
    except (ET.ParseError, KeyError) as e:
        print(f"Error parsing XML: {e}", file=sys.stderr)
        sys.exit(1)

    # Assign job IDs to processes for tracking
    for i, job in enumerate(jobs):
        job['_job_id'] = job['id']

    results = run_jobs(capacity, jobs)
    print(json.dumps(results))

