import sys
import json
import os
import subprocess
from xml.etree import ElementTree as ET
from collections import deque

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    capacity = int(root.attrib['capacity'])
    jobs = []
    for job_elem in root.findall('job'):
        job = {
            'id': job_elem.attrib['id'],
            'cmd': job_elem.attrib['cmd'],
            'weight': int(job_elem.attrib['weight'])
        }
        jobs.append(job)
    return capacity, jobs

def run_jobs(capacity, jobs):
    active_jobs = deque()
    completed_jobs = {}
    job_queue = deque(jobs)

    while job_queue or active_jobs:
        # Add new jobs to active queue if capacity allows
        while job_queue and sum(w for w in [j['weight'] for j in active_jobs]) < capacity:
            next_job = job_queue.popleft()
            p = subprocess.Popen(next_job['cmd'].split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            active_jobs.append(p)
            active_jobs.append({'id': next_job['id'], 'weight': next_job['weight']})

        # Check for completed jobs and update capacity
        completed = []
        for i, p in enumerate(active_jobs):
            if p is not None and p.poll() is not None:
                job_id = p['id']
                exit_code = p.poll()
                completed_jobs[job_id] = exit_code
                completed.append(i)
        for idx in sorted(completed, reverse=True):
            del active_jobs[idx]

    return completed_jobs

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    try:
        capacity, jobs = parse_xml(xml_path)
    except (ET.ParseError, KeyError) as e:
        sys.exit(f"Invalid XML: {e}")

    completed = run_jobs(capacity, jobs)
    print(json.dumps(completed))

if __name__ == "__main__":
    main()
